(function(){'use strict';
const C=SN,A=SNArt,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=localStorage}catch{}const db=new C.Store(storage);let s=C.newSession(),teacher=false,learner='1',errors={},saveMessage='Start a session to save your work',noticeTimer=null,pendingImport=null,printMode='report';
const btn=(action,label,cls='',extra='')=>`<button type="button" data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
const src=(id)=>C.sources[id]?`<a href="${C.sources[id][1]}" target="_blank" rel="noopener">${esc(C.sources[id][0])}</a>`:esc(id);
const fieldId=(g,f)=>'field-'+g+'-'+f;
function toast(text){$('#notice').className='notice';$('#notice').textContent=text;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').textContent='',6500)}
function save(){try{db.save(s);saveMessage='Saved on this device · '+new Date(s.updatedAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});$('#save-status')&&($('#save-status').textContent=saveMessage);return true}catch(e){saveMessage=e.message==='CONFLICT'?'Newer work exists in another tab. Open Sessions to reload or duplicate.':e.message;$('#save-status')&&($('#save-status').textContent=saveMessage);return false}}
function openDialog(title,body,footer=''){const d=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialoghead"><h2>${esc(title)}</h2>${btn('close','Close','small')}</div><div class="dialogbody">${body}</div>${footer?'<div class="navbottom">'+footer+'</div>':''}`;if(!d.open)d.showModal();}
function summary(message=''){const items=Object.entries(errors);return `<div id="error-summary" class="error-summary" tabindex="-1">${message?'<p>'+esc(message)+'</p>':''}${items.length?'<h3>Let’s check these fields</h3><ul>'+items.map(([k,v])=>`<li><a href="#${esc(k)}">${esc(v)}</a></li>`).join('')+'</ul>':''}</div>`}
function inputHTML(g,f){const id=fieldId(g.id,f.id),k=C.key(g.id,f.id),v=s.inputs[k]||'',err=errors[id],attrs=`id="${id}" data-input="${k}" aria-invalid="${!!err}" ${err?`aria-describedby="${id}-error"`:''}`;let control;
if(f.kind==='select')control=`<select ${attrs}><option value="">Choose…</option>${f.options.map(([value,label])=>`<option value="${esc(value)}" ${v===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
else if(f.kind==='text')control=`<textarea ${attrs} maxlength="600">${esc(v)}</textarea>`;
else control=`<div class="numeric-wrap"><input ${attrs} type="text" inputmode="${['exponent','coefficient','decimal'].includes(f.kind)?'decimal':'text'}" autocomplete="off" spellcheck="false" maxlength="100" value="${esc(v)}">${f.kind==='exponent'||f.id.endsWith('Deviation')?btn('minus','−','minus',`data-target="${id}" aria-label="Toggle minus sign for ${esc(f.label)}"`):''}</div>`;
return `<div class="field ${f.kind==='text'?'wide':''}"><label for="${id}">${esc(f.label)}</label>${control}${err?`<span class="error" id="${id}-error">${esc(err)}</span>`:''}</div>`}
function groupHTML(g){const state=C.status(s,g.id),r=C.raw(s,g.id),o=g.operation;let fields=g.fields;if(g.type==='transfer')fields=fields.filter(f=>r.mode==='paper'?['mode','submission'].includes(f.id):f.id!=='submission');const op=!!o;
return `<section class="card ${op?(o.domain==='Microscopic'?'micro':'macro'):''}" id="group-${g.id}"><div class="cardhead"><div><div class="tag">${esc(op?o.domain+' · '+o.op:g.id.replace(/[abAB]$/,''))}</div><h3>${esc(g.title)}</h3><span class="badge ${state}">${esc(state.replaceAll('-',' '))}</span></div>${g.type==='transfer'?'':btn('help','?','help',`data-group="${g.id}" aria-label="Help: ${esc(g.title)}"`)}</div><p>${esc(g.prompt)}</p>${o?'<div class="expression">'+esc(o.expression)+'</div>':''}${g.type==='scale'&&s.track==='B'?'<p class="smallprint muted">Moon diameter: 3.5 × 10⁶ m. Mean Earth–Moon distance: 3.84 × 10⁸ m.</p>':''}${g.type==='measurement'?measurementTargets():''}<div class="fields">${fields.map(f=>inputHTML(g,f)).join('')}</div>${fields.some(f=>f.id==='a')?`<div class="mathpreview" id="preview-${g.id}">${r.a?esc(r.a)+' × 10<sup>'+esc(r.n)+'</sup>':''}</div>`:''}<div class="checkline">${btn('check','Check work','primary',`data-group="${g.id}"`)}${state==='checked'?'<span class="result">Checked against the supplied model.</span>':state==='bypassed'?'<span class="result">Teacher bypass recorded; outcome stays provisional.</span>':''}</div>${op?'<p class="science-note">'+(o.id==='C04a'||o.id==='C05a'?'Ideal diameter model.':o.id==='C04b'||o.id==='C05b'||o.id==='C07b'?'Use the supplied rounded scientific values.':'Authored science-context example, not an experimental observation.')+'</p>':''}</section>`}
function measurementTargets(){return `<div class="factbox">${C.measurements[s.track].map(([,label,target,tol])=>esc(label)+': '+target+' mm, tolerance ±'+tol+' mm').join('<br>')}<br>Deviation = measured − target. Endpoints count as within tolerance.</div>`}
function countDone(){const gs=C.activeGroups(s);return [gs.filter(g=>g.type==='transfer'?C.submissionOK(s,g.id):C.ok(s,g.id)).length,gs.length]}
function header(){const [done,total]=countDone();return `<header class="masthead"><div class="brand"><div class="brand-icon">10<sup>n</sup></div><div><strong>Powers of Ten</strong><span class="eyebrow">Scale of Reality Lab · v${C.VERSION}</span></div></div><div class="toolbar"><span id="save-status">${esc(saveMessage)}</span>${btn('save','Save','small')}${btn('export','Export progress','small')}${btn('sessions','Sessions','small')}${btn('print-menu','Print','small')}${btn('teacher','Teacher','small')}</div></header><nav class="steps" aria-label="Investigation stages">${C.stages.map((name,i)=>`<button class="step ${s.currentStage===i+1?'active':''}" data-action="stage" data-stage="${i+1}" ${s.currentStage===i+1?'aria-current="step"':''}><span>0${i+1} ${i+1<s.currentStage?'·':''}</span>${esc(name)}</button>`).join('')}</nav>${!db.available?'<div class="hint" style="margin:15px 30px">Device storage is unavailable. Keep this tab open and export progress before leaving.</div>':''}<main id="main" tabindex="-1">${s.currentStage>1?`<div class="sectiontop"><div><p class="eyebrow">${s.currentStage<=4?'Day 1 · Investigate & plan':'Day 2 · Build & explain'} / Chapter 0${s.currentStage}</p><h2>${esc(C.stages[s.currentStage-1])}</h2><p>${esc(s.teamAlias||'Your exhibit team')} · ${esc(s.track==='A'?'Microscopic Enlargement':'Earth–Moon Desktop Model')}</p></div><div><span class="badge">${done} / ${total} checkpoints</span><div class="progressbar"><i style="width:${100*done/total}%"></i></div></div></div>`:''}${summary()}`}
function nav(){return `<div class="navbottom">${s.currentStage>1?btn('back','← Back'):''}<div class="toolbar">${btn('export','Export progress')}${s.currentStage<8?btn('next',s.currentStage===4?'Save plan · Day 2 →':'Check & continue →','primary'):btn('print-menu','Print your exhibit','primary')}</div></div>`}
function render(){const bodies=[commission,notation,calculations,planning,construction,verification,gallery,publish];$('#app').innerHTML=header()+bodies[s.currentStage-1]()+nav()+`</main><footer class="footer"><span>A WILLIAM MCADA PRODUCT · © 2026 William McAda</span><span>App ${C.VERSION} · Content ${C.CONTENT} · Local, alias-only progress</span></footer>`;}
function commission(){return `<section class="hero"><div class="hero-copy"><p class="eyebrow">Museum investigation / 01</p><h1>Too small.<br>Too far.<br><em>Make it real.</em></h1><p>A museum needs your help. Repair its scale labels, investigate extraordinary quantities, and build an exhibit visitors can understand.</p><div class="hero-count"><span><b>2</b>size worlds</span><span><b>8</b>calculations</span><span><b>1</b>physical exhibit</span></div></div><div class="hero-art">${A.hero()}</div></section><div class="intro-grid"><section class="panel"><p class="eyebrow">Your exhibit team</p><h2>Begin the investigation</h2><p class="muted">Use aliases, not full names. You’ll work together, then each complete a separate exit response.</p><div class="fields"><div class="field wide"><label for="team">Team alias</label><input id="team" data-meta="teamAlias" maxlength="64" value="${esc(s.teamAlias)}" placeholder="e.g. Team Orion"></div><div class="field"><label for="learner1">Learner 1 alias</label><input id="learner1" data-meta="student1" maxlength="64" value="${esc(s.students[0])}" placeholder="e.g. A1"></div><div class="field"><label for="learner2">Learner 2 alias</label><input id="learner2" data-meta="student2" maxlength="64" value="${esc(s.students[1])}" placeholder="e.g. A2"></div><div class="field"><label for="planner">Start as Planner</label><select id="planner" data-meta="planner"><option value="1" ${s.roles.planner==='1'?'selected':''}>Learner 1</option><option value="2" ${s.roles.planner==='2'?'selected':''}>Learner 2</option></select></div></div><p class="smallprint muted">The other learner checks. Swap at chapter breaks. Scientific-notation operations should already be familiar; this is an application project.</p>${btn('next','Enter the museum →','primary')}</section><aside class="panel soft"><p class="eyebrow">The commission</p><h2>One question.<br>Two ways to build.</h2><p>How can a model represent something too small or too large to experience directly?</p><ol class="stepslist"><li>Investigate notation, units, and both size ranges.</li><li>Build a cell enlargement or Earth–Moon reduction.</li><li>Measure, repair, explain, and publish.</li></ol><p class="smallprint">Two proposed 45-minute lessons. Paper/card, a ruler, tape, markers, and scissors. No microscope or live specimens needed.</p>${btn('import','Resume from a progress file')}</aside></div>`}
function notation(){return `<div class="panel"><h3>Move between worlds</h3><p>Use the complete values, not the exponent alone. These are decade bins for lengths in meters; icons are not drawn at one physical scale.</p><div class="axis-wrap">${A.axis()}</div><details><summary>Accessible magnitude-map description</summary><p>DNA width is in the 10⁻⁹ m decade; a cell diameter in 10⁻⁶; Earth diameter in 10⁷; Earth–Moon distance in 10⁸; Sun diameter in 10⁹; Earth–Sun distance in 10¹¹. Each step multiplies length by ten.</p></details><p class="factbox">Unit reference: 1 m = 100 cm = 1000 mm = 10⁶ µm = 10⁹ nm.</p></div><div class="cards">${C.activeGroups(s,2).map(groupHTML).join('')}</div>`}
function calculations(){return `<div class="panel"><div class="sectiontop"><div><h3>Eight repairs for the museum</h3><p>Work in both worlds. Show coefficient/exponent work, then give a normalized result and its unit.</p></div>${btn('calculator','Coefficient calculator')}</div><p class="smallprint muted">A calculator may help with coefficients. You still choose the exponent, units, and normalized representation. Swap Planner and Checker after each operation pair.</p></div><div class="cards">${C.activeGroups(s,3).map(groupHTML).join('')}</div>`}
function planning(){return `<div class="track-options">${['A','B'].map(t=>`<button class="track-option" data-action="track" data-track="${t}" aria-pressed="${s.track===t}"><span class="badge">Track ${t} · ${t==='A'?'Enlargement':'Reduction'}</span>${A.track(t)}<h3>${t==='A'?'Microscopic Enlargement':'Earth–Moon Desktop Model'}</h3><p>${t==='A'?'Turn an 8 µm cell into a 16 cm paper model. What will be too large—or too small—at the same scale?':'Let a 20 mm Earth set the scale for the Moon and its distance. Can the Sun fit on your desk?'}</p></button>`).join('')}</div><p class="smallprint muted" style="margin:18px 0">Switching tracks retains your other draft. Both tracks require all eight operations. You’ll inspect the other model in the gallery.</p>${groupHTML(C.getGroup(s,'C08'+s.track))}<div class="panel"><h3>Finish Day 1</h3><p>Check your plan, print the build sheet, export progress, and prepare materials. The model remains a plan until you build and measure it.</p><div class="toolbar">${btn('print-direct','Build sheet & templates','',`data-mode="build"`)}${btn('calculator','Coefficient calculator')}${btn('export','Export progress')}</div></div>`}
function trackBanner(){return `<div class="track-banner">${A.track(s.track)}<div><p class="eyebrow">${s.track==='A'?'Microscopic enlargement':'Desktop reduction'}</p><h3>${s.track==='A'?'A cell you can hold':'The space between worlds'}</h3><p>Original explanatory diagram. Responsive screen pictures are not physical rulers.</p></div></div>`}
function construction(){return trackBanner()+`<div class="layout"><section class="panel"><h3>Build from your checked plan</h3><ol class="stepslist">${s.track==='A'?'<li>Draw or use the calibrated guide for a 160 mm diameter paper/card cell.</li><li>Suggest a biconcave disc with a shallow depression. Keep the center intact: no nucleus and no hole.</li><li>Only diameter is part of the scale claim. Any thickness is illustrative.</li><li>Measure your finished model with a ruler; do not copy the planned target into the measurement record.</li>':'<li>Prepare a 20 mm Earth and a Moon with a 5.5 mm construction target. Keep the exact calculated Moon diameter on your sheet.</li><li>Mark both circle centers. Join three 200 mm distance segments, or measure 600 mm on a string/strip.</li><li>Put the centers at the endpoints. Edges can extend beyond the strip. The gap is measured center to center.</li><li>A larger Moon symbol must be labeled “not to size scale” and cannot replace the scaled Moon.</li>'}</ol><div class="hint">Print at 100%, not Fit to page. Measure the 50 mm calibration line first. If it differs by more than 0.5 mm, reprint or construct using a ruler.</div><label class="inlinecheck"><input type="checkbox" data-meta="built" ${s.built[s.track]?'checked':''}>We have constructed this physical model and are ready to measure it.</label><div class="field"><label for="builder">Builder (the other learner verifies)</label><select id="builder" data-meta="builder"><option value="1" ${s.roles.builder==='1'?'selected':''}>${esc(s.students[0]||'Learner 1')}</option><option value="2" ${s.roles.builder==='2'?'selected':''}>${esc(s.students[1]||'Learner 2')}</option></select></div><p style="margin-top:18px">${btn('rebuild','Record a rebuild / physical change')}</p></section><aside class="panel"><h3>Materials</h3><p>Paper/card, ruler, pencil, eraser, markers, tape, and child-appropriate scissors.</p>${s.track==='B'?'<p>Also: 60 cm string or joined paper strip.</p>':''}<p class="smallprint muted">A screen picture is not evidence of physical construction. Printer scaling and joins must be checked with a real ruler.</p>${btn('print-direct','Print build sheet','primary',`data-mode="build"`)}<p style="margin-top:12px">${btn('print-direct','Print dimensional templates','',`data-mode="templates"`)}</p></aside></div>`}
function verification(){const gid='C09'+s.track,checked=C.ok(s,gid);return trackBanner()+groupHTML(C.getGroup(s,gid))+(checked?`<section class="panel"><h3>${C.fit(s)?'Reported measurements fit the tolerance':'Your report is valid; the model needs repair'}</h3><p>${C.fit(s)?'This checks your numbers. A person still needs to inspect the physical object.':'Keep the honest measurement record. Adjust the physical model, record a rebuild, then measure again. You may continue to explain the mismatch.'}</p>${measurementTable()}<p>Physical inspection: <strong>${esc(C.reviewState(s,'inspection'))}</strong></p>${btn('teacher','Record teacher / peer inspection')}</section>`:'')}
function sourceCards(){return `<div class="sourcegrid">${C.objects.map(o=>`<article class="sourcecard">${A.object(o[0])}<h3>${esc(o[1])}</h3><p>${esc(o[2])}</p><b>${esc(o[3])} ${esc(o[4])}</b><p>${src(o[5])}</p><p>Rounded teaching value · diagram</p></article>`).join('')}</div>`}
function placardFields(){const t=s.track,p=C.placardData(s);function sel(f,label,opts){return `<div class="field"><label for="p-${f}">${label}</label><select id="p-${f}" data-input="placard${t}.${f}"><option value="">Choose…</option>${opts.map(([v,l])=>`<option value="${v}" ${p[f]===v?'selected':''}>${l}</option>`).join('')}</select></div>`}return `<section class="panel"><h3>Exhibit labels</h3><p>Missing or inconsistent labels lead to Calibration required. Your other checked mathematics stays intact.</p><div class="fields"><div class="field wide"><label for="p-title">Exhibit title</label><input id="p-title" maxlength="64" data-input="placard${t}.title" value="${esc(p.title)}"></div>${sel('property','What does the model show?',[['diameter','Cell diameter'],['diameter-distance','Earth/Moon diameters and center distance'],['mass','Mass']])}${sel('source','Source credit',[['R2','Histology Guide — cell'],['R3/R4','NASA — Earth and Moon'],['none','No source']])}${sel('scaleConfirmed','Confirm scale label',[['yes','I checked model:actual and direction'],['no','Needs checking']])}</div></section>`}
function gallery(){return `<div class="panel"><h3>The museum’s reference collection</h3><p class="muted">Use supplied rounded values consistently. Drawings explain; they are not new observations. The cell is a teaching exemplar, and orbital distances are mean values.</p>${sourceCards()}</div>${groupHTML(C.getGroup(s,'C10'+s.track))}${groupHTML(C.getGroup(s,'C11match'))}${groupHTML(C.getGroup(s,'C11'+s.track))}${placardFields()}<section class="panel"><div class="sectiontop"><div><p class="eyebrow">Separate evidence</p><h3>Each learner’s exit response</h3><p>Complete your own response without your partner’s help. Revisions are allowed and the first checked response is retained.</p></div>${btn('print-direct','Print answer-free slips','',`data-mode="transfers"`)}</div><div class="tabs">${['1','2'].map(t=>btn('learner',esc(s.students[Number(t)-1]||'Learner '+t),'',`data-learner="${t}" aria-pressed="${learner===t}"`)).join('')}</div>${groupHTML(C.getGroup(s,'C12'+learner))}</section>`}
function measurementTable(){const r=C.raw(s,'C09'+s.track);return `<table><thead><tr><th>Quantity</th><th>Target / tolerance</th><th>Reported measurement</th><th>Deviation (mm)</th></tr></thead><tbody>${C.measurements[s.track].map(([id,label,target,tol])=>`<tr><td>${label}</td><td>${target} ± ${tol} mm</td><td>${esc(r[id]||'Not recorded')} ${esc(r[id+'Unit'])}</td><td>${esc(r[id+'Deviation']||'Not checked')}</td></tr>`).join('')}</tbody></table>`}
function placard(){const p=C.placardData(s),r=C.raw(s,'C08'+s.track),m=C.raw(s,'C09'+s.track),l=C.raw(s,'C10'+s.track),text=C.raw(s,'C11'+s.track),source=s.track==='A'?'R2':'R3/R4';return `<article class="placard"><p class="eyebrow">Too Small, Too Far · ${esc(s.teamAlias)}</p><h3>${esc(p.title||'Untitled exhibit')}</h3><p>${s.track==='A'?'Red blood cell exemplar — supplied diameter 8 × 10⁻⁶ m.':'Earth: 1.28 × 10⁷ m diameter. Moon: 3.5 × 10⁶ m diameter. Mean center distance: 3.84 × 10⁸ m.'}</p><p><strong>Model:actual = ${esc(r.ratioM||'?')}:${esc(r.ratioA||'?')}</strong> · ${esc(r.direction==='enlarge'?'Enlargement':r.direction==='reduce'?'Reduction':'Direction not recorded')}</p><p>Reported ${s.track==='A'?'cell diameter: '+esc(m.cell||'not recorded')+' '+esc(m.cellUnit):'Earth diameter: '+esc(m.earth||'not recorded')+' '+esc(m.earthUnit)+'; Moon: '+esc(m.moon||'not recorded')+' '+esc(m.moonUnit)+'; center distance: '+esc(m.centers||'not recorded')+' '+esc(m.centersUnit)}.</p><p><strong>Model limit:</strong> ${esc(l.comparison||'Not selected')} → ${esc(l.size||'?')} ${l.comparison==='dna'?'mm':'m'}. ${esc(text.interpretation||'Interpretation not submitted.')}</p><p class="smallprint">Source credit entered: ${esc(p.source||'Missing')}. ${p.source===source?source.split('/').map(src).join(' / '):'Check source label.'}</p><p class="smallprint"><strong>${esc(C.outcome(s))}</strong> · Physical inspection: ${esc(C.reviewState(s,'inspection'))} · Interpretation: ${esc(C.reviewState(s,'interpretation'))}${s.imported?' · Imported evidence':''}</p></article>`}
function publish(){const out=C.outcome(s),[done,total]=countDone();return `<section class="verdict"><div class="copy"><p class="eyebrow">Your museum verdict</p><h2>${esc(out)}</h2><p>${out==='Featured exhibit'?'Your calculations, reported measurements, labels, and review records are current. Your exhibit can explain both what its scale preserves and what it leaves out.':out==='Calibration required'?'Your analyzed exhibit needs a repair. Check the measurements, labels, and review notes below; you can print this honest record and return to improve it.':out==='Exhibit ready for review'?'The submitted calculations and model measurements are current. A required human review is still pending.':out.startsWith('Provisional')?'A teacher bypass is active. The report preserves that context and does not treat it as checked mathematics.':'Finish or recheck the required evidence. You can still print a clearly labeled draft and export your work.'}</p></div>${A.outcome(out,s.track)}</section><div class="stats"><div class="stat"><b>${done}/${total}</b><span>Current/submitted checkpoints</span></div><div class="stat"><b>${s.attempts.length}</b><span>Retained checks · not a mastery score</span></div><div class="stat"><b>${C.fit(s)?'Within tolerance':'Check fit'}</b><span>Self-reported physical measurements</span></div></div>${placard()}<div class="cards"><section class="panel"><h3>Review desk</h3>${measurementTable()}<p>Physical inspection: <strong>${C.reviewState(s,'inspection')}</strong></p><p>Interpretation: <strong>${C.reviewState(s,'interpretation')}</strong></p><p>Labels: <strong>${C.labelsOK(s)?'Complete and consistent':'Repair required'}</strong></p>${btn('teacher','Open teacher review')}</section><section class="panel"><h3>Publish and preserve</h3><p>Print your exhibit, keep the progress file, and retain first-response evidence alongside corrected work.</p><div class="toolbar">${btn('print-direct','Student report','primary',`data-mode="report"`)}${btn('print-direct','Exhibit placard','',`data-mode="placard"`)}${btn('print-direct','Visitor passport','',`data-mode="visitor"`)}${btn('export','Export progress')}</div><p class="smallprint muted" style="margin-top:18px">Teacher review records are local classroom evidence, not tamper-proof certification. Pair work is not individual mastery.</p></section></div><details><summary>Checkpoint and review history</summary>${evidenceTable()}${reviewTable()}</details>`}
function evidenceTable(){return `<table><thead><tr><th>Checkpoint</th><th>Current state</th><th>Checks</th><th>First check</th><th>Help</th></tr></thead><tbody>${C.activeGroups(s).map(g=>{const a=s.attempts.filter(x=>x.group===g.id);return `<tr><td>${g.id}</td><td>${esc(C.status(s,g.id))}</td><td>${a.length}</td><td>${a.length?(a[0].passed?'Correct':'Needed revision'):'Not checked'}</td><td>${s.support.filter(h=>h.group===g.id).length}</td></tr>`}).join('')}</tbody></table>`}
function reviewTable(){return `<table><thead><tr><th>Review / track</th><th>Reviewer / status</th><th>Note</th></tr></thead><tbody>${s.reviews.map(r=>`<tr><td>${esc(r.type)} / ${r.track}</td><td>${esc(r.reviewer)} (${r.role}) — ${esc(r.status)}${r.fingerprint!==C.reviewFingerprint(s,r.type,r.track)?' · stale':''}</td><td>${esc(r.note)}</td></tr>`).join('')||'<tr><td colspan="3">No review recorded.</td></tr>'}</tbody></table>`}
function showHelp(gid){const g=C.getGroup(s,gid),h=C.help[g.help];s.support.push({group:gid,at:C.now()});save();openDialog('Help · '+g.title,`<dl class="answers"><dt>${esc(h[0])}</dt><dd>${esc(h[1])}</dd><dt>What to do</dt><dd>${esc(h[2])}</dd><dt>Different-number example</dt><dd>${esc(h[3])}</dd></dl>`)}
function checkGroup(id){const e=C.check(s,id);for(const k of Object.keys(errors))if(k.startsWith('field-'+id+'-'))delete errors[k];for(const [f,m]of Object.entries(e))errors[fieldId(id,f)]=C.getGroup(s,id).fields.find(x=>x.id===f).label+': '+m;save();render();if(Object.keys(e).length){$('#error-summary').focus();$('#error-summary').scrollIntoView({block:'start',behavior:'auto'})}else{toast('Work checked. Your first response and revisions are retained.');$('#group-'+id)?.scrollIntoView({block:'nearest'})}}
function proceed(){errors={};if(s.currentStage===1&&(!s.teamAlias.trim()||s.students.some(x=>!x.trim())||s.students[0]===s.students[1])){errors.team='Enter a team alias and two different learner aliases.'}else if(s.currentStage===5&&!s.built[s.track])errors['main']='Confirm that you constructed the physical model.';else for(const g of C.activeGroups(s,s.currentStage)){if(g.type==='transfer'&&C.submissionOK(s,g.id))continue;if(!C.ok(s,g.id)){const e=C.check(s,g.id);for(const [f,m]of Object.entries(e))errors[fieldId(g.id,f)]=g.title+': '+m;}}
if(Object.keys(errors).length){save();render();$('#error-summary').focus();return}if(s.currentStage===7&&C.outcome(s)!=='Draft — finish checks'&&!s.completedAt)s.completedAt=C.now();s.currentStage=Math.min(8,s.currentStage+1);save();render();window.scrollTo(0,0);$('#main').focus()}
function download(obj,name){const b=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCurrent(){download(s,'PowersOfTen_'+(s.teamAlias.replace(/[^\w-]/g,'_')||'session')+'.json');toast('Progress download requested. Keep the file as your portable backup.')}
function sessions(){let records=[];try{records=db.list()}catch(e){toast(e.message)}openDialog('Saved sessions',`<p>Each session includes both track drafts, attempts, reviews, and learner responses. Other applications use separate storage.</p><div class="toolbar">${btn('new','New session','primary')}${btn('duplicate','Duplicate current session')}${btn('import','Import progress')}${btn('backup','Export all as backup')}</div><p class="hint">If another tab holds newer work, choose its saved session below to reload, or duplicate your current in-memory work.</p>${records.map(r=>`<div class="session-row"><div><strong>${esc(r.session?.teamAlias||'Unreadable session')}</strong><span class="smallprint">${r.error?esc(r.error):esc(C.stages[r.session.currentStage-1])+' · '+esc(r.session.updatedAt)}</span></div><div class="toolbar">${r.session?btn('resume','Resume','small',`data-id="${esc(r.id)}"`):''}${btn('delete','Delete','small danger',`data-id="${esc(r.id)}"`)}</div></div>`).join('')||'<p style="margin-top:20px">No saved sessions yet.</p>'}<div class="navbottom">${btn('clear','Clear all Powers of Ten sessions','danger')}</div>`)}
function confirmDelete(ids){openDialog('Delete saved work?',`<p><strong>${ids.length} Powers of Ten session(s)</strong> will be deleted from this browser, including both track drafts, attempts, reviews, and transfers.</p><p>This is permanent locally. Recovery requires a previously exported progress file. Downloaded files and other apps remain unchanged.</p><div class="toolbar">${btn('backup','Export all as backup')}${btn('close','Cancel')}</div>`,btn('confirm-delete','Delete '+ids.length+' session(s)','danger',`data-ids="${esc(JSON.stringify(ids))}"`))}
function importFile(){const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=async()=>{try{if(!i.files[0])return;if(i.files[0].size>25*1024*1024)throw Error('File exceeds 25 MiB.');pendingImport=C.parseImport(await i.files[0].text());openDialog('Review imported progress',`<p>${pendingImport.length} valid session(s). Calculations are rechecked; imported reviews remain labeled as reported evidence.</p><ul>${pendingImport.map(x=>'<li>'+esc(x.teamAlias)+' · '+esc(C.stages[x.currentStage-1])+' · v'+esc(x.appVersion)+'</li>').join('')}</ul><p>Import as new copies preserves existing work. Replacing matching IDs requires a separate confirmation.</p><div class="toolbar">${btn('import-copies','Import as new copies','primary')}${btn('import-replace-preview','Replace matching IDs')}${btn('close','Cancel')}</div>`)}catch(e){openDialog('Import could not continue','<p>'+esc(e.message)+'</p><p>Current work has not been changed.</p>')}};i.click()}
function commitImport(replace){if(!pendingImport)return;const records=replace?pendingImport:pendingImport.map(C.duplicate);db.saveMany(records);s=records[0];pendingImport=null;$('#dialog').close();errors={};render();toast('Imported '+records.length+' session(s).')}
function teacherPanel(){teacher=true;openDialog('Teacher & inspection desk',`<p class="hint">Local classroom controls. Answers and records are not securely hidden or tamper-proof. Record an actual inspection or review; never substitute a software result for seeing the model.</p><div class="toolbar">${btn('print-direct','Teacher reference','',`data-mode="reference"`)}${btn('diagnostics','Run diagnostics')}${btn('diagnostic-export','Export diagnostics')}</div><h3 style="margin-top:25px">Record review for track ${s.track}</h3><p>Measurement truth is checked in person. The note must identify dimensions inspected and any disagreement. Amend the measurement record with a reason before accepting corrected data.</p><div class="fields"><div class="field"><label for="review-type">Review type</label><select id="review-type"><option value="inspection">Physical inspection</option><option value="interpretation">Scientific interpretation / labels</option><option value="C121">Learner 1 paper/oral transfer</option><option value="C122">Learner 2 paper/oral transfer</option></select></div><div class="field"><label for="reviewer">Reviewer alias</label><input id="reviewer" maxlength="64"></div><div class="field"><label for="review-role">Reviewer role</label><select id="review-role"><option value="teacher">Teacher</option><option value="peer">Peer (physical inspection only)</option></select></div><div class="field"><label for="review-status">Status</label><select id="review-status"><option value="pending">Pending</option><option value="accepted">Accepted</option><option value="repair-needed">Repair needed</option></select></div><div class="field wide"><label for="review-note">Actual inspection / review note (required)</label><textarea id="review-note" maxlength="400" placeholder="Name the measured quantities, values/units inspected, or reviewed interpretation. Record any mismatch."></textarea></div></div>${btn('record-review','Record review','primary')}${reviewTable()}<details><summary>Assistance / oral response / faulty checkpoint</summary><p>Oral responses can be transcribed in the corresponding response field before review. Bypass is for a faulty or inaccessible academic gate, with a recorded reason. It always produces a provisional outcome.</p><div class="fields"><div class="field"><label for="bypass-group">Checkpoint</label><select id="bypass-group">${C.activeGroups(s).map(g=>`<option value="${g.id}">${g.id} · ${esc(g.title)}</option>`).join('')}</select></div><div class="field"><label for="bypass-reviewer">Reviewer alias</label><input id="bypass-reviewer" maxlength="64"></div><div class="field wide"><label for="bypass-reason">Reason</label><textarea id="bypass-reason" maxlength="400"></textarea></div></div>${btn('bypass','Record provisional bypass','danger')}<p class="smallprint">Optional teacher rubric: math 8, representations 4, evidence/interpretation 4, usable documentation 4. Apply separately; no automatic gradebook mark.</p></details>`)}
function calculator(){openDialog('Coefficient calculator',`<p>Use this for coefficient arithmetic. You still enter and explain powers, units, and normalization.</p><div class="fields"><div class="field"><label for="calc-a">First number</label><input id="calc-a" inputmode="decimal"></div><div class="field"><label for="calc-b">Second number</label><input id="calc-b" inputmode="decimal"></div><div class="field"><label for="calc-op">Operation</label><select id="calc-op"><option>+</option><option>−</option><option>×</option><option>÷</option></select></div></div>${btn('calculate','Calculate','primary')}<p id="calc-result" role="status" style="margin-top:15px"></p>`)}
function printHeader(label,page){return `<div class="printheader">POWERS OF TEN / ${esc(label)} · ${esc(s.teamAlias||'Draft')} · ${esc(C.outcome(s))}</div><div class="printfooter">A WILLIAM MCADA PRODUCT · App ${C.VERSION} · Content ${C.CONTENT} · ${new Date().toLocaleDateString()} · Page ${page}</div>`}
function sheet(title,body,page){return `<section class="print-sheet">${printHeader(title,page)}<h1>${esc(title)}</h1>${body}</section>`}
function responseSummary(g,r){if(!r)return '';const pow=(a,n)=>esc(a||'?')+' × 10<sup>'+esc(n||'0')+'</sup>';if(g.operation){const o=g.operation;return (o.c?'Work: '+esc(r.c||'?')+' × 10<sup>'+esc(r.e||'?')+'</sup>':'Rewrite: ('+esc(r.left||'?')+' '+o.op+' '+esc(r.right||'?')+') × 10<sup>'+esc(r.common||'?')+'</sup>')+'<br>Final: '+pow(r.a,r.n)+' '+esc(r.unit||'?');}if(g.type==='sci')return pow(r.a,r.n)+' m';if(g.type==='transfer'&&r.mode!=='paper')return pow(r.a,r.n)+' m = '+esc(r.decimal||'?')+' m<br>'+esc(r.direction||'?')+'; scale interpretation '+esc(r.scale||'?')+' mm';return g.fields.filter(f=>r[f.id]).map(f=>esc(f.id)+': '+esc(r[f.id])).join('; ')}
function responseTable(gs){return `<table><thead><tr><th>Task</th><th>Current response / work</th><th>First checked response</th><th>State</th></tr></thead><tbody>${gs.map(g=>{const r=C.raw(s,g.id),first=s.attempts.find(a=>a.group===g.id),response=o=>responseSummary(g,o);return `<tr><td>${g.id}<br>${esc(g.title)}</td><td>${response(r)||'Not entered'}</td><td>${first?response(first.response):'Not checked'}</td><td>${esc(C.status(s,g.id))}<br>${s.support.filter(h=>h.group===g.id).length} help opens</td></tr>`}).join('')}</tbody></table>`}
function calibration(){return `<p>Print at <strong>100%, not Fit to page</strong>. Check this line: 50 mm (acceptable 49.5–50.5 mm). If incorrect, reprint or build with a ruler.</p><svg class="template-svg" xmlns="http://www.w3.org/2000/svg" width="60mm" height="12mm" viewBox="0 0 60 12" role="img" aria-label="50 millimeter calibration line"><path d="M5 6H55M5 2V10M55 2V10" stroke="black" stroke-width="0.3" fill="none"/></svg>`}
function buildPrint(){const t=s.track,r=C.raw(s,'C08'+t);return sheet('Physical model · build sheet',`<p>${t==='A'?'Microscopic Enlargement':'Earth–Moon Desktop Model'} · plan status: ${esc(C.status(s,'C08'+t))}</p><p>Model:actual = ${esc(r.ratioM||'?')}:${esc(r.ratioA||'?')} · ${esc(r.direction||'not selected')}. Check the plan before building.</p>${t==='A'?'<p>Actual diameter 8 × 10⁻⁶ m; planned model diameter 16 cm. Suggest a biconcave disc with an intact center, no nucleus or hole. Thickness is not part of this scale claim.</p>':'<p>Earth diameter 20 mm. Exact Moon calculation: '+esc(r.moon||'not checked')+' mm; construction target: '+esc(r.rounded||'not checked')+' mm. Center-to-center distance: '+esc(r.distance||'not checked')+' mm. Circle edges may overhang strip endpoints.</p>'}${calibration()}<table><thead><tr><th>Quantity</th><th>Target / tolerance</th><th>Actual measurement + unit</th><th>Measured − target (mm)</th></tr></thead><tbody>${C.measurements[t].map(([,label,target,tol])=>`<tr style="height:20mm"><td>${label}</td><td>${target} ± ${tol} mm</td><td></td><td></td></tr>`).join('')}</tbody></table><p>Tool / resolution: _______________________________</p><p>Inspector alias / role: ____________________________</p><p>Inspection status / values checked / note: __________________________________</p><p>Interpretation and review are separate from software checking. Never copy targets as measurements.</p>`,1)}
function templates(){let pages=[];if(s.track==='A'){pages.push(sheet('Cell model guide',calibration()+`<p>160 mm diameter. Depict a shallow depression; leave the center intact. Measure your finished model.</p><svg class="template-svg" xmlns="http://www.w3.org/2000/svg" width="170mm" height="170mm" viewBox="0 0 170 170" role="img" aria-label="160 mm cell diameter guide"><circle cx="85" cy="85" r="80" fill="none" stroke="black" stroke-width=".25"/><ellipse cx="85" cy="85" rx="33" ry="21" fill="none" stroke="#888" stroke-dasharray="1 2" stroke-width=".2"/><path d="M5 85H165M85 5V165" stroke="#aaa" stroke-width=".15"/></svg>`,1))}else{pages.push(sheet('Earth and Moon size guides',calibration()+`<p>Earth diameter 20 mm; Moon target 5.5 mm. Exact Moon calculation is 5.46875 mm, rounded once for construction.</p><svg class="template-svg" xmlns="http://www.w3.org/2000/svg" width="80mm" height="35mm" viewBox="0 0 80 35" role="img" aria-label="Earth 20 mm and Moon 5.5 mm diameter templates"><g fill="none" stroke="black" stroke-width=".2"><circle cx="20" cy="18" r="10"/><circle cx="58" cy="18" r="2.75"/><path d="M18 18H22M20 16V20M56 18H60M58 16V20"/></g></svg><p>Distance strips follow: three measured 200 mm segments = 600 mm. Extra tabs join the paper and do not add distance. Align the marked endpoints exactly, then measure the assembled center-to-center distance with a ruler.</p>`,1));for(let i=0;i<3;i++)pages.push(sheet('Distance segment '+(i+1)+' of 3',`<div style="display:flex;gap:8mm;align-items:flex-start"><svg class="template-svg" xmlns="http://www.w3.org/2000/svg" width="55mm" height="220mm" viewBox="0 0 55 220" role="img" aria-label="200 mm distance segment with joining tabs"><rect x="8" y="0.2" width="25" height="219.6" fill="none" stroke="#777" stroke-width=".2"/><path d="M20 10V210M10 10H30M10 210H30" stroke="black" stroke-width=".3"/><path d="M8 10H33M8 210H33" stroke="#888" stroke-width=".2" stroke-dasharray="1 1"/><text x="36" y="12" font-size="3">${i*200} mm</text><text x="36" y="211" font-size="3">${(i+1)*200} mm</text><text x="21" y="100" font-size="3" transform="rotate(90 21 100)">Segment ${i+1}: 200 mm</text></svg><div style="width:95mm"><p>200 mm measured length. Join endpoint to endpoint. Do not include the 10 mm tabs in the measured length.</p>${calibration()}<p>Assemble three segments and measure 600 mm between the two model centers. Do not measure between circle edges.</p></div></div>`,i+2))}return pages.join('').replaceAll('class="print-sheet"','class="print-sheet dimension-sheet"')}
function reference(){const data=C.objects.map(o=>`<tr><td>${esc(o[1])} — ${o[2]}</td><td>${esc(o[3])} ${esc(o[4])}</td><td>${src(o[5])}</td></tr>`).join('');return sheet('Teacher reference · notation and operations',`<p>Use exact classroom arithmetic on the rounded supplied values. Normalization is a separate requirement. No hidden significant-figure rule.</p><table><tr><th>Task</th><th>Answer / work</th></tr><tr><td>C01</td><td>8 × 10⁻⁶; 1.28 × 10⁷; 0.000000002; 384,000,000 m</td></tr><tr><td>C02</td><td>DNA &lt; specimen &lt; cell; ten times cell = 8 × 10⁻⁵ m; one decade larger.</td></tr><tr><td>C03</td><td>8 µm = 0.000008 m = 0.008 mm = 8000 nm; 1.28 × 10⁹ cm = 1.28 × 10⁷ m.</td></tr>${C.ops.map(o=>`<tr><td>${o.id}<br>${esc(o.expression)}</td><td>${o.c?`Raw coefficient ${o.c}, exponent ${o.e}. `:'Match either common exponent without changing inputs. '}Final ${o.a} × 10<sup>${o.n}</sup> ${o.unit==='widths'?'diameter-widths (dimensionless)':o.unit}.</td></tr>`).join('')}</table><p>C05a allows 8 or 8 × 10⁰; other operation finals require normalized notation. C06a equivalent 31.5 × 10⁻⁶ needs normalization. Zero is never accepted for a nonzero microscopic result.</p>`,1)+sheet('Teacher reference · models and review',`<h2>Microscopic Enlargement</h2><p>0.16 m ÷ (8 × 10⁻⁶ m) = 20,000; model:actual = 20,000:1. Target 160 mm ±2 mm. Person at scale: 34,000 m = 34 km; DNA width: 0.04 mm.</p><h2>Earth–Moon reduction</h2><p>k = 1/640,000,000 = 1.5625 × 10⁻⁹. Model:actual = 1:640,000,000. Earth 20 ±1 mm; Moon exact 5.46875 mm, construction 5.5 ±1 mm; centers 600 ±5 mm. Sun 2.1875 m; Earth–Sun distance 234.375 m.</p><h2>Common scale / transfers</h2><p>3 m ÷ 2 mm = 1500. Earth/cell = 1.6 × 10¹². One common linear scale exists mathematically but is impractical within the supplied limits.</p><p>Learner 1: 3 × 10⁻⁵ m = 0.00003 m; enlargement 5000:1; 1 mm actual → 5000 mm model. Learner 2: 6 × 10⁸ m = 600,000,000 m; reduction 1:5000; 1 mm model → 5000 mm actual.</p><h2>Review honestly</h2><p>All cell/Earth/Moon/Sun labels measure diameter; DNA measures width; Earth–Moon/Earth–Sun measure distance; light measures speed. Drawings are explanatory diagrams. Inspect a real model and record measured quantities/units, reviewer, and status. A correct report of an out-of-tolerance model is not bad arithmetic.</p><p>Featured requires all current academic checks, in-tolerance measurements, correct labels, accepted physical/interpretation reviews and required transfer review. Missing work is Draft; bypass is Provisional; known mismatch is Calibration required; pending human review is Exhibit ready for review.</p><p>Interpretations must use the selected numerical limitation and state what the model preserves/omits. Grammar and craftsmanship are not scored. Peer physical inspection is allowed; interpretation and paper/oral transfer review require a teacher record.</p>`,2)+sheet('Teacher reference · scientific sources',`<table><tr><th>Quantity / property</th><th>Teaching value</th><th>Reference</th></tr>${data}</table><p>8 µm is a chosen cell exemplar, not every cell’s diameter. Original illustrations are not observations. Microchannels, probe paths, and transfer scenarios are authored models. Data sources are optional reference links; core work runs offline.</p><p>Optional rubric (teacher-applied only): math 8, representations 4, evidence/interpretation 4, communication/documentation 4. Pair scores do not establish individual mastery.</p>`,3)}
function galleryReport(){const t=s.track,r=C.raw(s,'C11'+t),l=C.raw(s,'C10'+t),p=C.placardData(s),latest=[...s.reviews].reverse().find(x=>x.type==='interpretation'&&x.track===t);const rows=[`<h2>${esc(C.outcome(s))}</h2><p><strong>${esc(p.title||'Untitled exhibit')}</strong> · Source label ${esc(p.source||'missing')} · Scale/property labels ${C.labelsOK(s)?'consistent':'need repair'}.</p>`,responseTable([C.getGroup(s,'C10'+t)]),`<p><strong>Scientific interpretation (teacher review: ${C.reviewState(s,'interpretation')}):</strong> ${esc(r.interpretation||'Not submitted')}</p>`,`<p><strong>Other-track visit:</strong> ${esc(r.visitor||'Not submitted')} · ${esc(r.otherDirection||'direction missing')}.</p>`,`<p><strong>Property matching (${C.status(s,'C11match')}):</strong> ${responseSummary(C.getGroup(s,'C11match'),C.raw(s,'C11match'))}</p>`,responseTable([C.getGroup(s,'C121'),C.getGroup(s,'C122')]),`<p><strong>Latest interpretation reviewer:</strong> ${latest?esc(latest.reviewer)+' ('+latest.role+'), '+esc(latest.status)+'. '+esc(latest.note):'Pending'}</p><p>Help opens ${s.support.length}; bypass records ${s.teacherOverrides.length}. Complete original contexts and review histories remain in the progress export. Corrected pair work is not independent mastery.</p>`];return `<table class="gallery-report"><thead><tr><th>Gallery evidence · ${esc(s.teamAlias)} · v${C.VERSION} · continued on further pages if needed</th></tr></thead><tbody>${rows.map(x=>'<tr><td>'+x+'</td></tr>').join('')}</tbody></table>`}
function printHTML(mode){if(mode==='templates')return templates();if(mode==='build')return buildPrint();if(mode==='placard')return sheet('Museum exhibit placard',placard(),1);if(mode==='reference')return reference();if(mode==='visitor')return sheet('Visitor passport',`<p>Visit the other model type or a teacher example.</p><p>Model examined: __________________________________</p><p>Scale ratio and enlargement/reduction: ___________________________</p><p>One quantity/property preserved: _________________________________</p><p>One feature omitted or impractical: _______________________________</p><p>Numerical evidence: _____________________________________________</p>`,1);if(mode==='transfers')return ['1','2'].map((t,i)=>sheet('Independent exit · learner '+t,`<p>Alias: ________________________ · Complete independently.</p><p>${esc(C.getGroup(s,'C12'+t).prompt)}</p><p>Normalized result: ________________________ m</p><p>Ordinary decimal: _________________________ m</p><p>Scale direction: ___________________________</p><p>${t==='1'?'1 mm actual represents how many model mm?':'1 mm model represents how many actual mm?'} __________________</p><p>Work / explanation:</p><div style="height:75mm"></div><p>Teacher receipt / review: _____________________________</p>`,i+1)).join('');
return sheet('Investigation record · notation',`<p>Team ${esc(s.teamAlias)} · Learners ${s.students.map(esc).join(' / ')}. Track ${s.track}. ${s.imported?'Imported evidence; not newly observed.':''}</p>${responseTable(C.activeGroups(s,2))}`,1)+sheet('Scientific calculations',`<p>All eight operations apply to both tracks. Current and first checked responses are retained separately.</p>${responseTable(C.activeGroups(s,3))}`,2)+sheet('Physical exhibit · plan and measurement',`<p>${s.track==='A'?'Microscopic Enlargement':'Earth–Moon Desktop Model'} · Original explanatory diagram, not physical measurement.</p><div class="art-preview">${A.track(s.track)}</div>${responseTable(C.activeGroups(s,4))}${measurementTable()}<p>Tool: ${esc(C.raw(s,'C09'+s.track).tool)}. Resolution/estimate: ${esc(C.raw(s,'C09'+s.track).resolution)} mm. Physical fit: ${C.fit(s)?'Within tolerance (self-report)':'Needs checking/repair'}. Inspection: ${C.reviewState(s,'inspection')}.</p><p>Inspector / note: ${(()=>{const r=[...s.reviews].reverse().find(x=>x.type==='inspection'&&x.track===s.track);return r?esc(r.reviewer)+' ('+r.role+') — '+esc(r.note):'Pending'})()}</p><p>Exact calculation and construction targets remain separate; distance is center to center.</p>`,3)+sheet('Gallery, transfer, and museum outcome',galleryReport(),4)}
function printMenu(mode='report'){printMode=mode;openDialog('Print studio',`<p>Choose one output. Student views exclude the teacher reference. Use A4 or Letter, portrait, 100% scale; turn off browser headers/footers.</p><div class="toolbar">${[['report','Student report'],['build','Build sheet'],['templates','Dimensional templates'],['placard','Exhibit placard'],['visitor','Visitor passport'],['transfers','Exit slips'],...(teacher?[['reference','Teacher reference']]:[])].map(([m,l])=>btn('preview-print',l,m===mode?'primary':'',`data-mode="${m}"`)).join('')}</div><div id="print-preview">${printHTML(mode)}</div>`,btn('print-now','Print / Save PDF','primary'))}
$('#app').addEventListener('input',onInput);$('#dialog').addEventListener('input',onInput);
function onInput(e){const el=e.target;if(el.dataset.input){try{C.setInput(s,el.dataset.input,el.value);const gid=el.dataset.input.split('.')[0],pr=$('#preview-'+gid),r=C.getGroup(s,gid)?C.raw(s,gid):null;if(pr&&r)pr.innerHTML=esc(r.a)+' × 10<sup>'+esc(r.n)+'</sup>'}catch(err){toast(err.message)}}else if(el.dataset.meta){const k=el.dataset.meta;if(k==='teamAlias')s.teamAlias=el.value;if(k==='student1'||k==='student2')s.students[k==='student1'?0:1]=el.value;if(k==='built')s.built[s.track]=el.checked;if(k==='planner'||k==='builder')s.roles[k]=el.value;}}
document.addEventListener('change',e=>{if(e.target.dataset.input||e.target.dataset.meta){save();if(e.target.dataset.input?.endsWith('.mode'))render();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{const a=b.dataset.action;if(a==='close'){$('#dialog').close();return}if(a==='save'){save();toast(saveMessage)}else if(a==='help')showHelp(b.dataset.group);else if(a==='check')checkGroup(b.dataset.group);else if(a==='next')proceed();else if(a==='back'){s.currentStage=Math.max(1,s.currentStage-1);errors={};save();render();window.scrollTo(0,0)}else if(a==='stage'){const n=Number(b.dataset.stage),m=C.missing(s,n);if(m.length&&n>s.currentStage){toast('First finish: '+m.join(', '));return}s.currentStage=n;errors={};save();render();window.scrollTo(0,0)}else if(a==='track'){s.track=b.dataset.track;errors={};save();render();toast('Track selected. The other draft and all operation evidence are retained.')}else if(a==='learner'){learner=b.dataset.learner;errors={};render();$('#group-C12'+learner)?.scrollIntoView({block:'center'})}else if(a==='minus'){const el=$('#'+b.dataset.target);el.value=el.value.startsWith('-')?el.value.slice(1):'-'+el.value;el.dispatchEvent(new Event('input',{bubbles:true}));save();el.focus()}else if(a==='rebuild'){if(s.buildRevisions[s.track]>=100)throw Error('Build revision limit reached. Export and start a new session.');s.buildRevisions[s.track]++;s.built[s.track]=false;save();render();toast('Rebuild recorded. Previous measurements retained; recheck after construction.')}else if(a==='export')exportCurrent();else if(a==='sessions')sessions();else if(a==='new'){if(!save()){openDialog('Preserve this work first','<p>The current session could not be saved. Export current progress before starting another session.</p><div class="toolbar">'+btn('export','Export progress')+btn('new-confirm','Start new session','danger')+btn('close','Cancel')+'</div>');return}s=C.newSession();errors={};$('#dialog').close();render()}else if(a==='new-confirm'){s=C.newSession();errors={};$('#dialog').close();render()}else if(a==='duplicate'){s=C.duplicate(s);save();$('#dialog').close();render()}else if(a==='resume'){const v=db.read(b.dataset.id);if(!v)throw Error('Session no longer exists.');s=v;errors={};$('#dialog').close();render()}else if(a==='backup'){const rows=db.list();if(rows.some(r=>r.error))throw Error('A saved record is unreadable. Export current work; recover unreadable data before clearing it.');download(C.bundle(rows.map(r=>r.session)),'PowersOfTen_all_sessions_backup.json');toast('Backup download requested.')}else if(a==='delete')confirmDelete([b.dataset.id]);else if(a==='clear')confirmDelete(db.ids());else if(a==='confirm-delete'){const ids=JSON.parse(b.dataset.ids);db.remove(ids);if(ids.includes(s.sessionId))s=C.newSession();$('#dialog').close();errors={};saveMessage='Deletion completed';render();toast('Deleted '+ids.length+' session(s).')}else if(a==='import')importFile();else if(a==='import-copies')commitImport(false);else if(a==='import-replace-preview')openDialog('Replace matching saved sessions?',`<p>This will replace records with the imported IDs: ${pendingImport.map(x=>esc(x.teamAlias)).join(', ')}. All other sessions remain.</p><p>Export a backup first. Cancellation keeps current work.</p><div class="toolbar">${btn('backup','Export current backup')}${btn('import-replace','Confirm replacement','danger')}${btn('close','Cancel')}</div>`);else if(a==='import-replace')commitImport(true);else if(a==='teacher')teacherPanel();else if(a==='record-review'){C.review(s,$('#review-type').value,$('#reviewer').value,$('#review-role').value,$('#review-status').value,$('#review-note').value);save();render();teacherPanel();toast('Review recorded for the current evidence.')}else if(a==='bypass'){C.bypass(s,$('#bypass-group').value,$('#bypass-reviewer').value,$('#bypass-reason').value);save();render();teacherPanel();toast('Provisional bypass recorded.')}else if(a==='diagnostics')openDialog('Built-in diagnostics','<ul>'+C.diagnostics().map(x=>'<li>'+esc(x.name)+': '+(x.passed?'Passed':'FAILED')+'</li>').join('')+'</ul><p>Reference arithmetic only. This does not test a physical model, printer, or device.</p>');else if(a==='diagnostic-export')download({project:'powers-of-ten',app:C.VERSION,content:C.CONTENT,at:C.now(),storageAvailable:db.available,checks:C.diagnostics()},'PowersOfTen_diagnostics.json');else if(a==='calculator')calculator();else if(a==='calculate'){const x=C.q($('#calc-a').value),y=C.q($('#calc-b').value),op=$('#calc-op').value,z=op==='+'?x.add(y):op==='−'?x.sub(y):op==='×'?x.mul(y):x.div(y);$('#calc-result').textContent='Exact result: '+z.str()+' · decimal display: '+z.num();}else if(a==='print-menu')printMenu();else if(a==='print-direct'||a==='preview-print'){if(b.dataset.mode==='reference'&&!teacher)return;printMenu(b.dataset.mode)}else if(a==='print-now'){$('#print-root').innerHTML=printHTML(printMode);$('#dialog').close();window.print();}}catch(err){toast(err.message);}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('storage',e=>{if(e.key===C.PREFIX+'session:'+s.sessionId){saveMessage='Saved work changed in another tab. Open Sessions to reload or duplicate.';$('#save-status')&&($('#save-status').textContent=saveMessage)}});
window.addEventListener('beforeunload',e=>{if(!db.available){e.preventDefault();e.returnValue='Export progress before leaving.'}});
window.SNApp={get state(){return s},setState(v){s=C.validateSession(v,false);errors={};render()},render,printHTML,store:db};render();
})();
